vars.signature:
var (
	// ErrCompile indicates a program could not be parsed or compiled. Errors
	// wrapping it are of concrete type *CompileError.
	ErrCompile = errors.New("jq: compile error")

	// ErrSyntax indicates the lexer or parser rejected the program text. It is
	// wrapped by *CompileError in addition to ErrCompile.
	ErrSyntax = errors.New("jq: syntax error")

	// ErrUndefined indicates the program referenced a function, variable or
	// label that is not defined.
	ErrUndefined = errors.New("jq: undefined symbol")

	// ErrRuntime indicates the program failed while running. Errors wrapping it
	// are of concrete type *RuntimeError.
	ErrRuntime = errors.New("jq: runtime error")

	// ErrType indicates a value of the wrong type reached an operator or
	// builtin, for example "1 + {}".
	ErrType = errors.New("jq: type error")

	// ErrStepLimit indicates evaluation exceeded the step budget (see
	// Query.WithMaxSteps). It guards against non-terminating programs such as
	// "repeat(.)" and cannot be caught by the program's own try/catch.
	ErrStepLimit = errors.New("jq: step limit exceeded")

	// ErrBreak indicates a "break $label" escaped its enclosing "label $label"
	// expression, which jq reports as an uncaught break.
	ErrBreak = errors.New("jq: break outside of label")
)

types.signature:
type CompileError struct {
	// Program is the full jq program text that failed to compile.
	Program string
	// Offset is the byte offset within Program where the error was detected.
	Offset int
	// Msg describes the problem.
	Msg string
}

type Query struct {
	// contains filtered or unexported fields
}

type RuntimeError struct {
	// Msg is the human readable message, matching jq's wording where practical.
	Msg string
	// contains filtered or unexported fields
}
